<script>
document.querySelectorAll('.service-tabs button').forEach((button) => button.addEventListener('click', () => { document.querySelectorAll('.service-tabs button,.work-panel').forEach((el) => el.classList.remove('active')); button.classList.add('active'); document.querySelector('[data-panel="' + button.dataset.tab + '"]')?.classList.add('active'); }));
document.querySelectorAll('[data-quick]').forEach((button) => button.addEventListener('click', () => { const input = document.getElementById('islem_adi'); if (input) { input.value = button.dataset.quick; input.focus(); } }));
document.querySelectorAll('[data-months]').forEach((button) => button.addEventListener('click', () => { const months = Number(button.dataset.months); const hidden = document.querySelector('input[name="bakim_periyodu"]'); const date = document.getElementById('sonraki_bakim_tarihi'); const next = new Date(); next.setMonth(next.getMonth() + months); if (hidden) hidden.value = months; if (date) date.value = next.toISOString().slice(0,10); document.querySelectorAll('[data-months]').forEach((item) => item.classList.toggle('active', item === button)); }));
</script>
